        || MarkConfig::validateFont($this->font)
        || MarkConfig::validateFontSize($this->fontSize)
        || MarkConfig::validateFontStyle($this->fontStyle)
        || MarkConfig::validateFontWeight($this->fontWeight)
        || MarkConfig::validateHref($this->href)
        || MarkConfig::validateInterpolate($this->interpolate)
        || MarkConfig::validateLimit($this->limit)
        || MarkConfig::validateOpacity($this->opacity)
        || MarkConfig::validateOrient($this->orient)
        || MarkConfig::validateRadius($this->radius)
        || MarkConfig::validateShape($this->shape)
        || MarkConfig::validateSize($this->size)
        || MarkConfig::validateStroke($this->stroke)
        || MarkConfig::validateStrokeDash($this->strokeDash)
        || MarkConfig::validateStrokeDashOffset($this->strokeDashOffset)
