        $out->{'angle'} = $this->toAngle();
        $out->{'baseline'} = $this->toBaseline();
        $out->{'color'} = $this->toColor();
        $out->{'cursor'} = $this->toCursor();
        $out->{'dx'} = $this->toDx();
