        ,MarkConfig::fromAngle($obj->{'angle'})
        ,MarkConfig::fromBaseline($obj->{'baseline'})
        ,MarkConfig::fromColor($obj->{'color'})
        ,MarkConfig::fromCursor($obj->{'cursor'})
        ,MarkConfig::fromDx($obj->{'dx'})
