    public static function fromFontWeight(string|float|null $value): FontWeight|float|null {
        if (is_null($value)) {
            return $value; /*null*/
        } elseif (is_string($value) && in_array($value, ['normal', 'bold'], true)) {
            return FontWeight::from($value); /*enum*/
        } elseif (is_float($value) || is_int($value)) {
            return $value; /*float*/
        } else {
            throw new Exception('Cannot deserialize union value in TickConfig');
