     * @param FontWeight|float|null
     * @return bool
     * @throws Exception
     */
    public static function validateFontWeight(FontWeight|float|null $value): bool {
        if (is_null($value)) {
            if (!is_null($value)) {
                throw new Exception("Attribute Error:TickConfig::fontWeight");
            }
        } elseif ($value instanceof FontWeight) {
            FontWeight::to($value);
        } elseif (is_float($value) || is_int($value)) {
            if (!is_float($value) && !is_int($value)) {
                throw new Exception("Attribute Error:TickConfig::fontWeight");
            }
            if ($value < 100) throw new Exception("Attribute Error");
            if ($value > 900) throw new Exception("Attribute Error");
        } else {
            throw new Exception("Attribute Error:TickConfig::fontWeight");
        }
        return true;
    }

